    13	function validateReport(input: unknown): ReportInput {
    14	  if (!input || typeof input !== "object") throw new Error("invalid report");
    15	  const value = input as Partial<ReportInput>;
    16	  if (!value.accountId || !value.title) throw new Error("invalid report");
    17	  return { accountId: value.accountId, title: value.title };
    18	}

